#!/bin/bash
target="http://portal.otono.example"; proxy_version=$(curl -s -m 5 -X INVALID "$target" | grep -ioE '[a-zA-Z0-9_-]+/[0-9]+\.[0-9]+' | head -n 1); if [ -z "$proxy_version" ]; then proxy_version=$(curl -s -I -m 5 "$target" | grep -i '^server:' | awk '{print $2}' | tr -d '\r'); fi; for method in OPTIONS TRACE; do time_total=$(curl -s -o /dev/null -w "%{time_total}" -m 5 -X "$method" "$target"); done; curl -s -I -m 5 "$target" | grep -i "error" | sort > /dev/null; echo "$proxy_version"; echo "trace-method-discrepancy"
